const cfg = $input.first().json;
const tz = 'America/Sao_Paulo';
const hoje = cfg.data_teste && String(cfg.data_teste).trim()
  ? String(cfg.data_teste).trim()
  : new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const base = `https://raw.githubusercontent.com/${cfg.repo}/${cfg.branch}/fila/${hoje}`;

let post;
try {
  post = await this.helpers.httpRequest({ url: `${base}/post.json`, qs: { t: Date.now() }, json: true });
} catch (e) {
  return [{ json: { resultado: 'sem post para hoje', data: hoje } }];
}
if (typeof post === 'string') post = JSON.parse(post);
if (post.status !== 'aprovado') {
  return [{ json: { resultado: `não publicado (status: ${post.status})`, data: hoje } }];
}

const G = `https://graph.facebook.com/${cfg.graph_version}`;
const tok = cfg.access_token;
const enviar = (caminho, corpo) => this.helpers.httpRequest({
  method: 'POST', url: `${G}/${caminho}`, body: { ...corpo, access_token: tok }, json: true,
});
const urls = post.imagens.map(f => `${base}/${f}`);

let criacao;
if (urls.length === 1) {
  criacao = (await enviar(`${cfg.ig_user_id}/media`, { image_url: urls[0], caption: post.legenda })).id;
} else {
  const filhos = [];
  for (const u of urls) {
    filhos.push((await enviar(`${cfg.ig_user_id}/media`, { image_url: u, is_carousel_item: true })).id);
  }
  criacao = (await enviar(`${cfg.ig_user_id}/media`, {
    media_type: 'CAROUSEL', children: filhos.join(','), caption: post.legenda,
  })).id;
}

for (let i = 0; i < 12; i++) {
  const st = await this.helpers.httpRequest({ url: `${G}/${criacao}`, qs: { fields: 'status_code', access_token: tok }, json: true });
  if (st.status_code === 'FINISHED') break;
  if (st.status_code === 'ERROR') throw new Error('O Instagram recusou a mídia deste post.');
  await new Promise(r => setTimeout(r, 5000));
}

const pub = await enviar(`${cfg.ig_user_id}/media_publish`, { creation_id: criacao });
return [{ json: { resultado: 'publicado', data: hoje, tema: post.tema, media_id: pub.id } }];
